-- Omarchy system theme bridge: loads the aether colorscheme spec generated by
-- `omarchy theme set` (~/.local/state/omarchy/current/theme/neovim.lua).
--
-- Only the aether plugin entry is registered. The generated file also ships a
-- LazyVim entry (colorscheme = "aether") which is intentionally skipped so
-- mfd-paper/mfd-amber stay the default and aether activates only when
-- mfd-theme-toggle is in omarchy mode (:colorscheme aether).
--
-- Note: the generated colors are baked into the plugin opts at startup, so
-- after `omarchy theme set <other>` restart Neovim to pick the new palette.
local function omarchy_aether_spec()
  local path = vim.fn.expand("$HOME/.local/state/omarchy/current/theme/neovim.lua")
  if vim.fn.filereadable(path) == 0 then
    return nil
  end
  local ok, spec = pcall(dofile, path)
  if not ok or type(spec) ~= "table" then
    return nil
  end
  local entries = spec
  if type(spec[1]) ~= "table" then
    entries = { spec }
  end
  for _, entry in ipairs(entries) do
    if type(entry) == "table" and entry.name == "aether" then
      return entry
    end
  end
  return nil
end

local spec = omarchy_aether_spec()
if spec == nil then
  return {}
end
return { spec }
